-- Classic 1.60: vanilla (1.12) values of the legacy spells (VMaNGOS spell_template, latest row of build <= 5875): damage, heal, absorb, weapon damage,
-- energize, per-combo-point points, the spell power factor and the numbers of the main aura effects (modifiers, damage / healing / crit / hit mods, stats, attack power).
-- The 70291 client data differs from vanilla for part of them (Defias Evoker Flamestrike 11829: 479 where vanilla is 75 + 1d13; player Shadow Bolt rank 10 25307:
-- about 257 where vanilla is 481 + 1d57). Used for every caster of the legacy spell: SpellMgr::LoadClassicSpellValues, SpellInfo.cpp CalcBaseValue / CalcValue.
-- An aura row is used only while the client effect has the same effect, aura and misc value. Replaces 2026_10_10_01 (schema: 2026_10_10_20). Safe to run again.
